B=(1,1);
H=(-2.41,-0.41);
C=(2.41,-0.41);
G=(-2.41,-2.41);
D=(2.41,-2.41);
F=(-1,-3.82);
I=(1,-3.82);
draw(A--B--C--D--I--F--G--H--cycle,linewidth(0.7));
label("$A$",A,N);
label("$B$",B,N);
label("$C$",C,E);
label("$D$",D,E);
